// Builds staticresources/fcEngineBundle.js for FcEngine.page from the two
// sources Jest tests: lwc/fcCore/fcCore.js and engine/fcEngine.js.
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const CORE = path.join(ROOT, 'force-app/main/default/lwc/fcCore/fcCore.js');
const ENGINE = path.join(ROOT, 'engine/fcEngine.js');
const OUT = path.join(ROOT, 'force-app/main/default/staticresources/fcEngineBundle.js');

function buildBundle() {
    const core = fs.readFileSync(CORE, 'utf8');
    const names = [];
    const body = core.replace(/^export function (\w+)/gm, (match, name) => {
        names.push(name);
        return 'function ' + name;
    });
    if (/^\s*(import|export)\s/m.test(body)) {
        throw new Error('fcCore.js may only use "export function" declarations');
    }
    return (
        '// GENERATED by scripts/build-bundle.js. Do not edit; run "npm run build".\n' +
        '(function (root) {\n' +
        body +
        '\nroot.FcCore = { ' + names.join(', ') + ' };\n' +
        '})(typeof self !== "undefined" ? self : this);\n' +
        fs.readFileSync(ENGINE, 'utf8')
    );
}

module.exports = { buildBundle };

if (require.main === module) {
    fs.writeFileSync(OUT, buildBundle());
    console.log('Wrote ' + path.relative(ROOT, OUT));
}
